const inp=[...document.querySelectorAll('input:not([type=checkbox]):not([type=radio]), textarea')].filter(e=>e.getBoundingClientRect().width>0);
const out = inp.map(e=>{ const s=getComputedStyle(e); const ph=getComputedStyle(e,'::placeholder').color; let bg=s.backgroundColor, p=e; while(bg==='rgba(0, 0, 0, 0)'&&p.parentElement){p=p.parentElement; bg=getComputedStyle(p).backgroundColor;} return {id:e.id, cls:e.className, placeholder:e.placeholder, ph, bg, border:s.border, ratio: cr(ph,bg), textRatio: cr(s.color,bg)}; });
// also synthetic: tertiary placeholder on raised (documented 'Lifted Charcoal')
const root=getComputedStyle(document.documentElement);
return {out, tertiaryOnRaised: cr(root.getPropertyValue('--text-tertiary').trim(), root.getPropertyValue('--surface-raised').trim()), tertiaryOnContact: cr(root.getPropertyValue('--text-tertiary').trim(), root.getPropertyValue('--surface-contact').trim()), layout: {listTop: window.__m('search').listTop, firstRowY: window.__m('search').firstRowY}};
